{
  "root_cause": "Pikaday's global keydown listener (added when keyboardInput:true) prevents default for ArrowLeft/Right/Up/Down regardless of which element has focus, causing the caret not to move in other inputs like the notes field when the calendar is visible.",
  "repair_strategy": "Modify Pikaday's _onKeyChange handler to early‑return unless the bound field (opts.field) is the active element, preserving default arrow‑key behavior elsewhere while keeping date navigation functional when the field itself is focused.",
  "edits": [
    {
      "path": "pikaday.js",
      "sha256": "662123ec9f429dee9cffaacfcf89b05ed9c3c30a78d33ecfd113e6778349cc77",
      "before": "        self._onKeyChange = function(e)
        {
            e = e || window.event;

            if (self.isVisible()) {

                switch(e.keyCode){
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        e.preventDefault();
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                }
            }
        };",
      "after": "        self._onKeyChange = function(e)
        {
            e = e || window.event;

            if (self.isVisible()) {
                // Only react to keyboard input when the bound field has focus
                if (!(opts.field && e.target === opts.field)) {
                    return;
                }

                switch(e.keyCode){
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        e.preventDefault();
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                }
            }
        };"
    }
  ],
  "expected_accessibility_effect": "ArrowLeft will now move the caret in the notes input when the calendar is visible but the notes field is focused, allowing users to insert a space and correct text. Keyboard users can still navigate dates with arrow keys when the delivery-date field has focus.",
  "functional_risks": [
    "If a user focuses another element while intending to navigate the calendar with arrow keys, date navigation will be disabled (they must focus the date field first).",
    "The change relies on the field being the active element; if the field is hidden or removed, arrow keys will have no effect in the calendar.",
    "Esc/Enter to blur the field will only work when the field has focus, which matches existing behavior."
  ],
  "verification_requirements": [
    "Verify that typing 'Gate4', pressing ArrowLeft, then space results in notes value 'Gate 4'.",
    "Confirm that ArrowLeft/Right/Up/Down still change the selected date when the delivery-date input is focused.",
    "Ensure Esc closes the calendar and blurs the delivery-date field when it is focused.",
    "Check that Tab order and focus movement to/from the notes and delivery-date fields remain unchanged."
  ]
}

